<?php require_once __DIR__.'/../includes/functions.php';require_role(['admin','production']);$pdo=db();$statuses=['design_review','production','qc','packing','shipping','completed'];if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['id'];$st=$_POST['status'];$pdo->prepare("UPDATE orders SET status=? WHERE id=?")->execute([$st,$id]);$pdo->prepare("INSERT INTO order_status_history(order_id,status,changed_by) VALUES(?,?,?)")->execute([$id,$st,current_user()['id']]);redirect('production.php');}$rows=$pdo->query("SELECT o.*,u.name customer FROM orders o JOIN customers c ON c.id=o.customer_id JOIN users u ON u.id=c.user_id ORDER BY o.created_at DESC")->fetchAll();?><!doctype html><html lang="id"><head><?php include __DIR__.'/../includes/head.php';?></head><body><?php include __DIR__.'/../includes/header.php';?><main class="content"><h1>Production Kanban</h1><div class="kanban"><?php foreach($statuses as $st):?><section><h3><?=e(str_replace('_',' ',$st))?></h3><?php foreach($rows as $r) if($r['status']===$st):?><article class="kanban-card"><b><?=e($r['order_number'])?></b><p><?=e($r['customer'])?></p><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><?php foreach($statuses as $x):?><option <?=($x===$st?'selected':'')?> value="<?=$x?>"><?=e($x)?></option><?php endforeach;?></select><button>Move</button></form></article><?php endforeach;?></section><?php endforeach;?></div></main></body></html>